let state = null;

export function initialize(element, dotNetRef, timeoutSeconds) {
    const timeoutMs = timeoutSeconds * 1000;
    let isIdle = false;
    let timerId = null;

    function resetTimer() {
        clearTimeout(timerId);
        if (isIdle) {
            isIdle = false;
            dotNetRef.invokeMethodAsync("OnActiveCallback");
        }
        timerId = setTimeout(() => {
            isIdle = true;
            dotNetRef.invokeMethodAsync("OnIdleCallback");
        }, timeoutMs);
    }

    const events = ["mousemove", "keydown", "click", "scroll"];
    events.forEach(evt => element.addEventListener(evt, resetTimer, { passive: true }));

    // Start the initial idle countdown
    timerId = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("OnIdleCallback");
    }, timeoutMs);

    state = { element, events, resetTimer, timerId };
}

export function dispose() {
    if (!state) return;
    clearTimeout(state.timerId);
    state.events.forEach(evt =>
        state.element.removeEventListener(evt, state.resetTimer)
    );
    state = null;
}

